-- PetCare: estrutura do banco PostgreSQL (gerada com: python manage.py sqlmigrate core 0001).
-- Para criar o banco basta executar 'python manage.py migrate'; este arquivo documenta e permite criar a estrutura manualmente.
-- As tabelas internas do Django (auth/sessions/admin) são criadas pelo migrate.
BEGIN;
--
-- Create model Cliente
--
CREATE TABLE "core_cliente" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "nome" varchar(120) NOT NULL, "telefone" varchar(20) NOT NULL, "email" varchar(254) NOT NULL, "endereco" varchar(200) NOT NULL);
--
-- Create model Servico
--
CREATE TABLE "core_servico" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "nome" varchar(80) NOT NULL, "tipo" varchar(10) NOT NULL, "duracao_minutos" integer NOT NULL CHECK ("duracao_minutos" >= 0), "preco" numeric(8, 2) NOT NULL, "ativo" boolean NOT NULL);
--
-- Create model Funcionario
--
CREATE TABLE "core_funcionario" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "password" varchar(128) NOT NULL, "last_login" timestamp with time zone NULL, "is_superuser" boolean NOT NULL, "nome" varchar(120) NOT NULL, "email" varchar(254) NOT NULL UNIQUE, "perfil" varchar(15) NOT NULL, "especialidade" varchar(80) NOT NULL, "is_active" boolean NOT NULL);
CREATE TABLE "core_funcionario_groups" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "funcionario_id" bigint NOT NULL, "group_id" integer NOT NULL);
CREATE TABLE "core_funcionario_user_permissions" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "funcionario_id" bigint NOT NULL, "permission_id" integer NOT NULL);
--
-- Create model Pet
--
CREATE TABLE "core_pet" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "nome" varchar(80) NOT NULL, "especie" varchar(5) NOT NULL, "raca" varchar(80) NOT NULL, "data_nascimento" date NULL, "cliente_id" bigint NOT NULL);
--
-- Create model Agendamento
--
CREATE TABLE "core_agendamento" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "inicio" timestamp with time zone NOT NULL, "hora_fim" timestamp with time zone NOT NULL, "valor_cobrado" numeric(8, 2) NOT NULL, "status" varchar(10) NOT NULL, "observacoes" varchar(200) NOT NULL, "profissional_id" bigint NOT NULL, "pet_id" bigint NOT NULL, "servico_id" bigint NOT NULL);
--
-- Create model Receita
--
CREATE TABLE "core_receita" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "valor" numeric(8, 2) NOT NULL, "forma_pagamento" varchar(10) NOT NULL, "data_pagamento" date NOT NULL, "agendamento_id" bigint NOT NULL UNIQUE);
--
-- Create model Vacina
--
CREATE TABLE "core_vacina" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "nome" varchar(80) NOT NULL, "data_aplicacao" date NOT NULL, "data_proxima_dose" date NULL, "lote" varchar(40) NOT NULL, "aplicada_por_id" bigint NOT NULL, "pet_id" bigint NOT NULL);
CREATE INDEX "core_funcionario_email_62780fbb_like" ON "core_funcionario" ("email" varchar_pattern_ops);
ALTER TABLE "core_funcionario_groups" ADD CONSTRAINT "core_funcionario_groups_funcionario_id_group_id_9a33025b_uniq" UNIQUE ("funcionario_id", "group_id");
